describe('Dropdown Component Tests', () => {
  it('should display the dropdown with disabled option', () => {
    cy.visit('https://the-internet.herokuapp.com/dropdown');
    cy.get('#dropdown').should('be.visible');
    cy.get('#dropdown').contains('Option 1').should('be.visible');
    cy.get('#dropdown').contains('Option 2').should('be.visible');
    cy.get('#dropdown').contains('Option 3').should('be.visible');
    cy.get('#dropdown').contains('Option 4').should('be.visible');
    cy.get('#dropdown').contains('Option 5').should('be.visible');
  });

  it('should not change the URL when selecting an option', () => {
    cy.visit('https://the-internet.herokuapp.com/dropdown');
    cy.get('#dropdown').select('Option 2');
    cy.url().should('eq', 'https://the-internet.herokuapp.com/dropdown');
  });
});
